const completePage=document.getElementById("completePage");
function renderComplete(){const order=orders.find(o=>o.number===new URLSearchParams(location.search).get('id'));completePage.innerHTML=order?`<p class="eyebrow">ORDER COMPLETE</p><h1 tabindex="-1">주문이 완료되었습니다.</h1><p>주문 내역에서 배송 상태를 확인할 수 있습니다.</p><div class="completion-card"><p>주문번호 <strong>${escapeText(order.number)}</strong></p><p>${order.items.map(x=>escapeText(x.name)+' × '+x.qty).join(' · ')}</p><p>주문 금액 <strong>${won(order.total)}</strong></p></div><div class="completion-actions"><a class="outline" href="orders.html">주문 내역 확인</a><a class="outline" href="products.html">쇼핑 계속하기</a></div>`:EmptyStates.html('orderMissing');}
requireLogin(renderComplete);window.addEventListener("store-data-change",renderComplete);
